def read_admesh_global(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/ADMESH/GLOBAL``, ``/ADGLOB``, ``/ADGLOB/MESH`` (M113): Global adaptive meshing parameters::

        card 1:  Levelmax  Iadmrule  Tdelay  [Idt]
    """
    title, cards = _fixed_data(block) if block.fixed else _title_and_data(block)
    if not cards or cards[0].is_blank:
        cards = block.cards
    from ...model.entities import AdmeshGlobal

    level_max, iadm_rule, t_delay, istat_cnd = 0, 0, 0.0, 0
    if cards and not cards[0].is_blank:
        if block.fixed:
            f = cards[0].cut("ADMESH_GLOBAL_1")
            level_max = _ival(f[0]) if len(f) > 0 else 0
            iadm_rule = _ival(f[1]) if len(f) > 1 else 0
            t_delay = _fval(f[2], 0.0) if len(f) > 2 else 0.0
            istat_cnd = _ival(f[3]) if len(f) > 3 else 0
        else:
            t = cards[0].tokens()
            level_max = int(float(t[0])) if len(t) > 0 else 0
            iadm_rule = int(float(t[1])) if len(t) > 1 else 0
            t_delay = float(t[2]) if len(t) > 2 else 0.0
            istat_cnd = int(float(t[3])) if len(t) > 3 else 0

    model.admesh_global = AdmeshGlobal(
        level_max=level_max, iadm_rule=iadm_rule, t_delay=t_delay, istat_cnd=istat_cnd
    )




def read_admesh(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/ADMESH/<subtype>/id`` dispatcher (M143): Adaptive meshing controls."""
    from ...model.entities import AdmeshControl
    sub = block.parts[1].upper() if len(block.parts) > 1 else "GLOBAL"
    aid = block.user_id or 1
    title, cards = _fixed_data(block) if block.fixed else _title_and_data(block)

    if sub in ("GLOBAL", "MESH"):
        read_admesh_global(block, model, log)
        return

    if sub == "SET":
        from ...model.entities import AdmeshSet
        angle_crit, inilev, thkerr = 0.0, 0, 0.0
        grnd_id, level, tdelay = 0, 0, 0.0
        if cards and not cards[0].is_blank:
            if block.fixed:
                f = cards[0].cut("ADMESH_SET_1")
                angle_crit = _fval(f[0], 0.0) if len(f) > 0 else 0.0
                inilev = _ival(f[1], 0) if len(f) > 1 else 0
                thkerr = _fval(f[2], 0.0) if len(f) > 2 else 0.0
            else:
                t = cards[0].tokens()
                angle_crit = float(t[0]) if len(t) > 0 else 0.0
                inilev = int(float(t[1])) if len(t) > 1 else 0
                thkerr = float(t[2]) if len(t) > 2 else 0.0
        if len(cards) > 1 and not cards[1].is_blank:
            if block.fixed:
                f2 = cards[1].cut("ADMESH_SET_1")
                grnd_id = _ival(f2[0], 0) if len(f2) > 0 else 0
                level = _ival(f2[1], 0) if len(f2) > 1 else 0
                tdelay = _fval(f2[2], 0.0) if len(f2) > 2 else 0.0
            else:
                t2 = cards[1].tokens()
                grnd_id = int(float(t2[0])) if len(t2) > 0 else 0
                level = int(float(t2[1])) if len(t2) > 1 else 0
                tdelay = float(t2[2]) if len(t2) > 2 else 0.0
        adm_set = AdmeshSet(
            id=aid, title=title, angle_criteria=angle_crit, inilev=inilev,
            thkerr=thkerr, grnd_id=grnd_id, level=level, tdelay=tdelay
        )
        model.admesh_sets[aid] = adm_set
        model.admesh_controls[aid] = AdmeshControl(
            id=aid, title=title, subtype=sub, crit_level=inilev,
            h_min=thkerr, h_max=angle_crit, part_id=grnd_id
        )
        return

    crit_level = 0
    h_min, h_max = 0.0, 0.0
    part_id = 0
    if cards and not cards[0].is_blank:
        if block.fixed:
            f = cards[0].cut("ADMESH_PART_1")
            part_id = _ival(f[0]) if len(f) > 0 else 0
            crit_level = _ival(f[1]) if len(f) > 1 else 0
            h_min = _fval(f[2], 0.0) if len(f) > 2 else 0.0
            h_max = _fval(f[3], 0.0) if len(f) > 3 else 0.0
        else:
            t = cards[0].tokens()
            part_id = int(float(t[0])) if len(t) > 0 else 0
            crit_level = int(float(t[1])) if len(t) > 1 else 0
            h_min = float(t[2]) if len(t) > 2 else 0.0
            h_max = float(t[3]) if len(t) > 3 else 0.0
    model.admesh_controls[aid] = AdmeshControl(
        id=aid, title=title, subtype=sub, crit_level=crit_level,
        h_min=h_min, h_max=h_max, part_id=part_id
    )




