def read_fail_cockcroft(block: KeywordBlock, model: Model, log: MessageLog) -> None:
    """``/FAIL/COCKCROFT`` or ``/FAIL/COCKCROFT_LATHAM`` (M281): Cockcroft-Latham ductile failure model."""
    title, cards = _title_and_data(block)
    mat_id = block.user_id
    valid_cards = [c for c in cards if not c.is_blank and not c.raw.strip().startswith("#")]
    if not valid_cards:
        from ...model.entities import FailCockcroft, FailureModel
        type_str = "COCKCROFT_LATHAM" if "COCKCROFT_LATHAM" in block.keyword.upper() else "COCKCROFT"
        model.fail_cockcrofts[mat_id] = FailCockcroft(mat_id=mat_id, title=title)
        fm = FailureModel(type=type_str, ifail_sh=1, params={})
        model.raw_fails.append((mat_id, fm, block.source))
        return

    c0, alpha = 0.0, 1.0
    failip = 0
    fail_id = 0

    if block.fixed and "," not in valid_cards[0].raw:
        c1 = valid_cards[0].cut("FAIL_COCKCROFT_1") if "FAIL_COCKCROFT_1" in CARD_LAYOUTS else valid_cards[0].tokens()
        c0 = _fval(c1[0]) if len(c1) > 0 else 0.0
        alpha = _fval(c1[1], 1.0) if len(c1) > 1 and c1[1].strip() else 1.0
        failip = _ival(c1[2], 0) if len(c1) > 2 else 0

        if len(valid_cards) > 1:
            c2 = valid_cards[1].cut("FAIL_COCKCROFT_2") if "FAIL_COCKCROFT_2" in CARD_LAYOUTS else valid_cards[1].tokens()
            fail_id = _ival(c2[0], 0) if len(c2) > 0 else 0
    else:
        toks1 = valid_cards[0].tokens()
        c0 = float(toks1[0].rstrip(',')) if len(toks1) > 0 else 0.0
        alpha = float(toks1[1].rstrip(',')) if len(toks1) > 1 else 1.0
        failip = int(float(toks1[2].rstrip(','))) if len(toks1) > 2 else 0

        if len(valid_cards) > 1:
            toks2 = valid_cards[1].tokens()
            fail_id = int(float(toks2[0].rstrip(','))) if len(toks2) > 0 else 0

    from ...model.entities import FailCockcroft, FailureModel
    model.fail_cockcrofts[mat_id] = FailCockcroft(
        mat_id=mat_id, c0=c0, alpha=alpha, failip=failip,
        fail_id=fail_id, title=title,
    )
    params = {"c0": c0, "alpha": alpha, "failip": failip, "fail_id": fail_id}
    type_str = "COCKCROFT_LATHAM" if "COCKCROFT_LATHAM" in block.keyword.upper() else "COCKCROFT"
    fm = FailureModel(type=type_str, ifail_sh=1, params=params)
    model.raw_fails.append((mat_id, fm, block.source))




