    sigma_cftrr0, sigma_cftrrc, gamma_cftrr, p_cftrr, d_cftrr_max = 0.0, 1.0, 0.0, 1.0, 0.999
    if block.fixed and "," not in cards[0].raw:
        f = cards[0].cut("FAIL_LAD_COUPLE_FIBER_TENSION_RUPTURE_RATE_1")
        sigma_cftrr0 = _fval(f[0], 0.0) if len(f) > 0 else 0.0
